// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c) && actor != address(0));
        vm.deal(actor, amount);
        vm.prank(actor);
        try c.play{value: amount}() {
            // succeeded: reference has pot credited and in sync with balance
        } catch {
            // reverted: state fully rolled back, balance and pot both 0
        }
        // General rule: at every settled state, the contract's ether balance
        // equals the recorded pot. Reference: play credits pot with msg.value,
        // so losing draw -> balance 10 / pot 10; winning draw -> balance 0 / pot 0.
        // Mutant: never credits pot, so losing draw leaves balance 10, pot 0.
        assertTrue(address(c).balance == c.pot());
    }
}
